#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int u, v, w;
    bool operator<(const Edge& other) const {
        return w > other.w;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, B;
    cin >> N >> B;

    vector<Edge> edges(B);
    for (auto& e : edges) {
        cin >> e.u >> e.v >> e.w;
        --e.u;
        --e.v;
    }

    sort(edges.begin(), edges.end());

    vector<int> dsu(N), sz(N, 1);
    iota(dsu.begin(), dsu.end(), 0);

    auto find = [&](int x) {
        int root = x;
        while (dsu[root] != root) root = dsu[root];
        while (dsu[x] != x) {
            int next = dsu[x];
            dsu[x] = root;
            x = next;
        }
        return root;
    };

    vector<vector<pair<int, int>>> tree(N);
    for (const auto& e : edges) {
        int ru = find(e.u);
        int rv = find(e.v);
        if (ru == rv) continue;

        if (sz[ru] < sz[rv]) swap(ru, rv);
        dsu[rv] = ru;
        sz[ru] += sz[rv];

        tree[e.u].push_back({e.v, e.w});
        tree[e.v].push_back({e.u, e.w});
    }

    int LOG = 1;
    while ((1 << LOG) <= N) ++LOG;

    vector<vector<int>> parent(LOG, vector<int>(N));
    vector<vector<int>> minEdge(LOG, vector<int>(N, INT_MAX));
    vector<int> depth(N, 0);

    vector<int> stack = {0};
    parent[0][0] = 0;
    vector<bool> visited(N, false);
    visited[0] = true;

    while (!stack.empty()) {
        int v = stack.back();
        stack.pop_back();

        for (auto [to, w] : tree[v]) {
            if (visited[to]) continue;
            visited[to] = true;
            parent[0][to] = v;
            minEdge[0][to] = w;
            depth[to] = depth[v] + 1;
            stack.push_back(to);
        }
    }

    for (int k = 1; k < LOG; ++k) {
        for (int v = 0; v < N; ++v) {
            parent[k][v] = parent[k - 1][parent[k - 1][v]];
            minEdge[k][v] = min(minEdge[k - 1][v],
                                minEdge[k - 1][parent[k - 1][v]]);
        }
    }

    auto query = [&](int a, int b) {
        int answer = INT_MAX;

        if (depth[a] < depth[b]) swap(a, b);

        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; ++k) {
            if (diff & (1 << k)) {
                answer = min(answer, minEdge[k][a]);
                a = parent[k][a];
            }
        }

        if (a == b) return answer;

        for (int k = LOG - 1; k >= 0; --k) {
            if (parent[k][a] != parent[k][b]) {
                answer = min(answer, minEdge[k][a]);
                answer = min(answer, minEdge[k][b]);
                a = parent[k][a];
                b = parent[k][b];
            }
        }

        answer = min(answer, minEdge[0][a]);
        answer = min(answer, minEdge[0][b]);
        return answer;
    };

    int C;
    cin >> C;
    while (C--) {
        int X, Y;
        cin >> X >> Y;
        cout << query(X - 1, Y - 1) << '\n';
    }

    return 0;
}
